// Block (composition) — the controls above a result list: a scope Select with its label inside the
// box beside a search button, then a row of refine actions (filter, sort) and an optional toggle that
// narrows the list. Distinct from FilterBar, which lays out one labelled Select per facet with the
// active tags and a Clear action; here the facets live behind the refine actions (a sheet or menu the
// page opens) and only the scope stays on screen. Select, Button, Switch and Stack own all look and
// arrangement; the Block defines no tokens. Panel posture: it sits above the list it controls.
import type { ReactNode, Ref } from "react";
import { Text, type Key } from "react-aria-components";
import { Button } from "../components/Button";
import { Search } from "../components/icons";
import { Select, SelectItem } from "../components/Select";
import { Switch } from "../components/Switch";
import { Stack } from "../layouts/Stack";
import "./ListControls.css";

export interface ListControlsAction {
  /** Visible label, e.g. "Filter" or "Sort". */
  label: string;
  /** Leading icon; pass `size="1em"`. */
  icon?: ReactNode;
  onPress?: () => void;
}

export interface ListControlsProps {
  /** The scope the list shows, chosen from a short set (a network, a category). */
  scope: {
    label: string;
    options: { id: string; label: string }[];
    selectedKey?: Key | null;
    onSelectionChange?: (key: Key | null) => void;
  };
  /** Opens a search; renders the search button when given. */
  onSearchPress?: () => void;
  /** Accessible name of the search button. */
  searchLabel?: string;
  /** Refine actions in the second row, e.g. Filter and Sort. */
  actions?: ListControlsAction[];
  /** A toggle that narrows the list, at the end of the second row. */
  toggle?: { label: string; isSelected?: boolean; onChange?: (isSelected: boolean) => void };
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function ListControls({
  scope,
  onSearchPress,
  searchLabel = "Search",
  actions = [],
  toggle,
  className,
  ref,
}: ListControlsProps) {
  return (
    <Stack ref={ref} direction="column" gap="small" className={className ? `sd-listcontrols ${className}` : "sd-listcontrols"}>
      <Stack direction="row" gap="small" align="stretch">
        <Select
          className="sd-listcontrols__scope"
          label={scope.label}
          labelPlacement="inside"
          selectedKey={scope.selectedKey}
          onSelectionChange={scope.onSelectionChange}
        >
          {scope.options.map((option) => (
            <SelectItem key={option.id} id={option.id}>
              {option.label}
            </SelectItem>
          ))}
        </Select>
        {onSearchPress && (
          <Button variant="secondary" isIconOnly aria-label={searchLabel} onPress={onSearchPress}>
            <Search aria-hidden size="1em" />
          </Button>
        )}
      </Stack>
      {(actions.length > 0 || toggle) && (
        <Stack direction="row" justify="between" align="center" gap="small" wrap>
          <Stack direction="row" gap="x-small" align="center">
            {actions.map((action) => (
              <Button key={action.label} variant="secondary" onPress={action.onPress}>
                {action.icon}
                <Text>{action.label}</Text>
              </Button>
            ))}
          </Stack>
          {/* Its label ends the row under the search button's end edge, so it takes the end inset. */}
          {toggle && (
            <>
              <Switch size="small" isSelected={toggle.isSelected} onChange={toggle.onChange}>
                {toggle.label}
              </Switch>
            </>
          )}
        </Stack>
      )}
    </Stack>
  );
}

/* ListControls.css — .sd-listcontrols (Block)
   Arrangement only: the scope Select takes the row's free width beside the search button. */
.sd-listcontrols__scope {
  flex: 1 1 auto;
  min-inline-size: 0;
}
